/*
 * A395677  Numbers which are divisible by the sum of their base-7 digits.
 * https://oeis.org/A395677
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 101, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 7‑Harshad numbers (also called 7‑Niven numbers).
 * A(n) is the nth positive integer that is divisible by the sum of
 * its base‑7 digits.  The values are generated by a simple brute‑force
 * search; no closed form is known.  The function memoizes all previously
 * found terms so that subsequent calls are fast.
 */

#include <stdlib.h>

seq_t a(idx_t n) {
    /* Static state */
    static seq_t *arr = NULL;
    static size_t cap = 0;       /* array capacity            */
    static size_t count = 0;     /* number of terms generated */
    static seq_t cur = 1;        /* next candidate to test    */

    /* Ensure we have at least n terms */
    while (count < n) {
        /* Compute sum of base‑7 digits of 'cur' */
        seq_t sum = 0;
        seq_t temp = cur;
        while (temp > 0) {
            sum += temp % 7;
            temp /= 7;
        }

        /* Test Harshad condition */
        if (sum > 0 && cur % sum == 0) {
            /* Grow array if needed */
            if (count == cap) {
                size_t new_cap = cap == 0 ? 16 : cap * 2;
                seq_t *new_arr = (seq_t *)realloc(arr, new_cap * sizeof(seq_t));
                if (!new_arr) abort();      /* memory allocation failed */
                arr = new_arr;
                cap = new_cap;
            }
            arr[count++] = cur;
        }

        ++cur;
    }

    return arr[n - 1];
}
